SELECT tc.table_name AS tabla, tc.constraint_type AS tipo, tc.constraint_name AS nombre, kcu.column_name AS columna, ccu.table_name AS tabla_ref, ccu.column_name AS columna_ref FROM information_schema.table_constraints tc JOIN information_schema.key_column_usage kcu ON tc.constraint_name = kcu.constraint_name AND tc.table_schema = kcu.table_schema LEFT JOIN information_schema.constraint_column_usage ccu ON tc.constraint_name = ccu.constraint_name AND tc.constraint_type='FOREIGN KEY' WHERE tc.table_schema='public' AND tc.constraint_type IN ('PRIMARY KEY','FOREIGN KEY','UNIQUE') ORDER BY tc.table_name, tc.constraint_type, kcu.ordinal_position;
